Now,

\mathrm{e}^{1 / \mathrm{c}} \times \mathrm{e}^{1 / \mathrm{a}}=\mathrm{e}^{(\mathrm{a}+\mathrm{c}) / \mathrm{ac}}=\mathrm{e}^{2 \mathrm{~b} / \mathrm{ac}}=\left(\mathrm{e}^{\mathrm{b} / \mathrm{ac}}\right)^{2}

$\therefore \mathrm{e}^{1 / \mathrm{c}}, \mathrm{e}^{\mathrm{b} / \mathrm{ac}}, \mathrm{e}^{1 / \mathrm{a}}$ in G.P. with common ratio

\begin{array}{l}
=\frac{\mathrm{e}^{\mathrm{b} / \mathrm{ac}}}{\mathrm{e}^{1 / \mathrm{c}}}=\mathrm{e}^{(\mathrm{b}-\mathrm{a}) / \mathrm{ac}}=\mathrm{e}^{\mathrm{d} /(\mathrm{b}-\mathrm{d})(\mathrm{b}+\mathrm{d})} \\
=\mathrm{e}^{\mathrm{d} /\left(\mathrm{b}^{2}-\mathrm{d}^{2}\right)}
\end{array}

